WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET DEFINE OFF
ALTER SESSION SET TIME_ZONE='+09:00';
BEGIN
    IF USER <> 'GROUPWARE_BOOT' THEN RAISE_APPLICATION_ERROR(-20001,'Use GROUPWARE_BOOT, not SYSTEM.'); END IF;
END;
/
DECLARE
    employee_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO employee_count FROM EMPLOYEE;
    IF employee_count>0 THEN RAISE_APPLICATION_ERROR(-20002,'Data already exists; initialization stopped.'); END IF;
END;
/















