UPDATE EQUIPMENT E SET TOTAL_COUNT=GREATEST(TOTAL_COUNT,NVL((SELECT SUM(REQ_COUNT) FROM RENTAL_HISTORY R WHERE R.EQ_NO=E.EQ_NO AND R.STATUS IN ('승인대기','대여중')),0));
UPDATE EQUIPMENT E SET REMAIN_COUNT=TOTAL_COUNT-NVL((SELECT SUM(REQ_COUNT) FROM RENTAL_HISTORY R WHERE R.EQ_NO=E.EQ_NO AND R.STATUS IN ('승인대기','대여중')),0);
UPDATE EMPLOYEE E SET CUR_LEAVE=GREATEST(0,MAX_LEAVE-NVL((SELECT SUM(USE_DAYS) FROM LEAVE_HISTORY L WHERE L.EMP_NO=E.EMP_NO AND L.STATUS='승인완료'),0));

COMMIT;
